-- Drafts are never accepted. Only trusted operators can publish an immutable version.
create table public.legal_documents (
  kind text not null check(kind in ('terms','privacy','provider_terms')),
  version text not null check(char_length(version) between 1 and 80),
  content_sha256 text not null check(content_sha256 ~ '^[0-9a-f]{64}$'),
  content_json text not null check(jsonb_typeof(content_json::jsonb)='object'),
  status text not null default 'draft' check(status in ('draft','published','retired')),
  published_at timestamptz,
  primary key(kind,version),
  check((status='draft')=(published_at is null)),
  check(status='draft' or version not ilike '%draft%')
);
create unique index legal_current_document_idx on public.legal_documents(kind) where status='published';
create table public.legal_receipts (
  user_id uuid not null references auth.users(id) on delete cascade,
  kind text not null,
  version text not null,
  locale text not null check(locale in ('ka','en')),
  action text not null check((kind='privacy' and action='acknowledged') or (kind in ('terms','provider_terms') and action='agreed')),
  recorded_at timestamptz not null default now(),
  primary key(user_id,kind,version),
  foreign key(kind,version) references public.legal_documents(kind,version) on delete restrict
);
alter table public.legal_documents enable row level security;
alter table public.legal_receipts enable row level security;
revoke all on public.legal_documents,public.legal_receipts from public,anon,authenticated;
grant select on public.legal_documents to anon,authenticated;
grant select on public.legal_receipts to authenticated;
create policy published_legal_documents on public.legal_documents for select to anon,authenticated using(status in ('published','retired'));
create policy own_legal_receipts on public.legal_receipts for select to authenticated using(user_id=(select auth.uid()));
comment on table public.legal_receipts is 'Versioned agreement/notice receipts. Not marketing consent, never an authorization role. Writes only through the authenticated capture RPC.';
create schema legal_private;
revoke all on schema legal_private from public,anon,authenticated;
grant usage on schema legal_private to authenticated;
create function legal_private.protect_document() returns trigger language plpgsql security definer set search_path='' as $$
begin
  perform pg_advisory_xact_lock(hashtextextended('bloom_legal_registry',0));
  if tg_op='DELETE' then
    if old.status<>'draft' then raise exception 'published_legal_document_immutable' using errcode='22023'; end if;
    return old;
  end if;
  if tg_op='UPDATE' and old.status<>'draft' then
    if (new.kind,new.version,new.content_sha256,new.content_json,new.published_at) is distinct from (old.kind,old.version,old.content_sha256,old.content_json,old.published_at)
      or (new.status is distinct from old.status and not(old.status='published' and new.status='retired')) then
      raise exception 'published_legal_document_immutable' using errcode='22023';
    end if;
  end if;
  return new;
end $$;
revoke all on function legal_private.protect_document() from public,anon,authenticated;
create trigger protect_legal_document before insert or update or delete on public.legal_documents for each row execute function legal_private.protect_document();

create function legal_private.capture(p_versions jsonb,p_hashes jsonb,p_locale text,p_provider boolean)
returns void language plpgsql security definer set search_path='' as $$
declare actor uuid:=auth.uid(); doc public.legal_documents; expected text[]; actual integer:=0;
begin
  if actor is null then raise exception 'authentication_required' using errcode='42501'; end if;
  if p_locale is null or p_locale not in ('ka','en') or p_provider is null or p_versions is null or jsonb_typeof(p_versions)<>'object' or p_hashes is null or jsonb_typeof(p_hashes)<>'object' then raise exception 'invalid_legal_receipt' using errcode='22023'; end if;
  expected:=case when p_provider then array['terms','privacy','provider_terms'] else array['terms','privacy'] end;
  if (select count(*) from jsonb_object_keys(p_versions))<>cardinality(expected) or (select count(*) from jsonb_object_keys(p_hashes))<>cardinality(expected) then raise exception 'invalid_legal_receipt' using errcode='22023';end if;
  perform pg_advisory_xact_lock_shared(hashtextextended('bloom_legal_registry',0));
  for doc in select * from public.legal_documents where status='published' and kind=any(expected) loop
    actual:=actual+1;
    if p_versions->>doc.kind is distinct from doc.version or p_hashes->>doc.kind is distinct from doc.content_sha256 then raise exception 'legal_version_changed' using errcode='22023';end if;
    insert into public.legal_receipts(user_id,kind,version,locale,action)
      values(actor,doc.kind,doc.version,p_locale,case when doc.kind='privacy' then 'acknowledged' else 'agreed' end)
      on conflict(user_id,kind,version) do nothing;
  end loop;
  if actual<>cardinality(expected) then raise exception 'legal_documents_not_published' using errcode='22023';end if;
end $$;
create function public.record_legal_receipts(p_versions jsonb,p_hashes jsonb,p_locale text,p_provider boolean)
returns void language sql security invoker set search_path='' as $$ select legal_private.capture(p_versions,p_hashes,p_locale,p_provider) $$;
revoke all on function legal_private.capture(jsonb,jsonb,text,boolean),public.record_legal_receipts(jsonb,jsonb,text,boolean) from public,anon,authenticated;
grant execute on function legal_private.capture(jsonb,jsonb,text,boolean),public.record_legal_receipts(jsonb,jsonb,text,boolean) to authenticated;

-- Keep the same requirement at the data mutation boundary, including direct RPC clients.
-- With no published documents this preview remains usable and captures no fake consent.
create function legal_private.require_current(actor uuid,provider boolean) returns void language plpgsql security definer set search_path='' as $$
declare expected text[]; total integer;
begin
  perform pg_advisory_xact_lock_shared(hashtextextended('bloom_legal_registry',0));
  select count(*) into total from public.legal_documents where status='published';
  if total=0 then return;end if;
  expected:=case when provider then array['terms','privacy','provider_terms'] else array['terms','privacy'] end;
  if (select count(*) from public.legal_documents where status='published' and kind=any(expected))<>cardinality(expected) then raise exception 'legal_documents_not_published' using errcode='22023';end if;
  if actor is null or exists(select 1 from public.legal_documents d where d.status='published' and d.kind=any(expected) and not exists(select 1 from public.legal_receipts r where r.user_id=actor and r.kind=d.kind and r.version=d.version)) then raise exception 'legal_acceptance_required' using errcode='22023';end if;
end $$;
revoke all on function legal_private.require_current(uuid,boolean) from public,anon,authenticated;
create function legal_private.guard_provider_application() returns trigger language plpgsql security definer set search_path='' as $$
begin
  if tg_op='INSERT' then perform legal_private.require_current(new.user_id,true);
  elsif new.status='pending' and new.revision is distinct from old.revision then perform legal_private.require_current(new.user_id,true);end if;
  return new;
end $$;
create function legal_private.guard_booking() returns trigger language plpgsql security definer set search_path='' as $$
declare owner uuid;
begin
  perform legal_private.require_current(new.customer_id,false);
  select b.owner_id into owner from public.venues v join public.businesses b on b.id=v.business_id where v.id=new.venue_id;
  perform legal_private.require_current(owner,true);
  return new;
end $$;
create function legal_private.guard_publication() returns trigger language plpgsql security definer set search_path='' as $$
declare owner uuid;
begin
  if new.published then
    select owner_id into owner from public.businesses where id=new.business_id;
    perform legal_private.require_current(owner,true);
  end if;
  return new;
end $$;
revoke all on function legal_private.guard_provider_application(),legal_private.guard_booking(),legal_private.guard_publication() from public,anon,authenticated;
create trigger legal_provider_application before insert or update on public.provider_applications for each row execute function legal_private.guard_provider_application();
create trigger legal_booking before insert on public.appointments for each row execute function legal_private.guard_booking();
create trigger legal_publication before insert or update on public.venues for each row execute function legal_private.guard_publication();
